//! Structural codecs against the exact types emitted by wit-bindgen.

use crate::{
    Catalog, GenerateOptions, PackageName, RustSource,
    model::{Kind, Number, Schema, SchemaId},
    naming::{rust_case_name, rust_ident, rust_type_name},
};

pub(crate) fn emit(
    catalog: &Catalog,
    package: &PackageName,
    options: &GenerateOptions,
) -> Vec<RustSource> {
    let lib = format!(
        "// Generated by autostamp-mcp.\n\
         #![deny(unsafe_code)]\n\
         #[allow(unsafe_code)]\n\
         mod bindings {{\n\
         wit_bindgen::generate!({{ world: \"client\", path: \"wit\", generate_all, generate_unused_types: true, pub_export_macro: true }});\n\
         }}\n\
         pub use bindings::*;\n\
         mod codecs;\n\
         mod runtime;\n\
         #[cfg(target_arch = \"wasm32\")]\n\
         #[path = \"runtime/wasi.rs\"]\n\
         mod wasi;\n\
         #[cfg(target_arch = \"wasm32\")]\n\
         mod credentials;\n\
         #[cfg(target_arch = \"wasm32\")]\n\
         mod client;\n\
         #[cfg(target_arch = \"wasm32\")]\n\
         struct Component;\n\
         #[cfg(target_arch = \"wasm32\")]\n\
         #[allow(unsafe_code)]\n\
         mod component_export {{ use crate::Component; crate::bindings::export!(Component with_types_in crate::bindings); }}\n\
         use exports::{}::{}::tool;\n",
        rust_ident(package.namespace()),
        rust_ident(package.name()),
    );
    vec![
        RustSource {
            path: "lib.rs".into(),
            contents: lib,
        },
        RustSource {
            path: "codecs.rs".into(),
            contents: codecs(catalog),
        },
        RustSource {
            path: "client.rs".into(),
            contents: client(catalog, options),
        },
        RustSource {
            path: "credentials.rs".into(),
            contents: credentials(options),
        },
        RustSource {
            path: "runtime/mod.rs".into(),
            contents: include_str!("runtime/mod.rs").into(),
        },
        RustSource {
            path: "runtime/wire.rs".into(),
            contents: include_str!("runtime/wire.rs").into(),
        },
        RustSource {
            path: "runtime/wasi.rs".into(),
            contents: include_str!("runtime/wasi.rs").into(),
        },
    ]
}

fn credentials(options: &GenerateOptions) -> String {
    if options.bearer_secret.is_none() {
        return "pub(crate) fn load(_key: Option<&str>) -> Result<Option<String>, crate::runtime::Error> {\n    Ok(None)\n}\n".into();
    }
    r#"use crate::{runtime::Error, wasmcloud::secrets::{store, reveal}};

pub(crate) fn load(key: Option<&str>) -> Result<Option<String>, Error> {
    let Some(key) = key else { return Ok(None); };
    let secret = store::get(key)
        .map_err(|_| Error::Transport("could not load bearer secret".into()))?;
    let value = match reveal::reveal(&secret) {
        store::SecretValue::String(value) => value,
        store::SecretValue::Bytes(value) => String::from_utf8(value)
            .map_err(|_| Error::Transport("bearer secret must be UTF-8".into()))?,
    };
    if value.is_empty() || !value.bytes().all(|b| b.is_ascii_graphic()) {
        return Err(Error::Transport("bearer secret must be a nonempty visible ASCII token".into()));
    }
    Ok(Some(value))
}
"#
    .into()
}

fn client(catalog: &Catalog, options: &GenerateOptions) -> String {
    if catalog.tools.is_empty() {
        return "// The catalog declares no tool exports.\n".into();
    }
    let secret = options
        .bearer_secret
        .as_ref()
        .map_or_else(|| "None".into(), |key| format!("Some({key:?})"));
    let mut out = format!(
        "use crate::{{codecs, runtime, tool}};\n\
         const ENDPOINT: &str = {:?};\n\
         const SECRET: Option<&str> = {secret};\n\
         const LIMITS: runtime::Limits = runtime::Limits {{ request_timeout_ms: {}, max_response_bytes: {}, max_event_bytes: {} }};\n\n\
         fn runtime_error(error: runtime::Error) -> tool::Error {{\n\
             match error {{\n\
                 runtime::Error::Transport(message) => tool::Error::Transport(message),\n\
                 runtime::Error::Protocol(message) => tool::Error::Protocol(message),\n\
                 runtime::Error::ToolExecution(envelope) => tool::Error::ToolExecution(envelope),\n\
                 runtime::Error::ResultDecoding(message) => tool::Error::ResultDecoding(message),\n\
             }}\n\
         }}\n\n\
         impl tool::Guest for crate::Component {{\n",
        options.endpoint,
        options.limits.request_timeout_ms,
        options.limits.max_response_bytes,
        options.limits.max_event_bytes,
    );
    for tool in &catalog.tools {
        let input = schema(catalog, tool.input);
        let empty = matches!(&input.kind, Kind::Object { properties, additional: None } if properties.is_empty());
        let arguments = if empty {
            String::new()
        } else {
            format!("arguments: tool::{}", rust_type_name(&input.name))
        };
        let result = tool.output.map_or_else(
            || "String".into(),
            |_| format!("tool::{}", rust_type_name(&tool.result_name)),
        );
        out.push_str(&format!(
            "    fn {}({arguments}) -> Result<{result}, tool::Error> {{\n",
            rust_ident(&tool.name),
        ));
        if empty {
            out.push_str(
                "        let arguments = serde_json::Value::Object(serde_json::Map::new());\n",
            );
        } else {
            out.push_str(&format!(
                "        let arguments = codecs::encode_{}(&arguments)?;\n",
                tool.input
            ));
        }
        out.push_str(&format!(
            "        let envelope = crate::wasi::call(ENDPOINT, SECRET, LIMITS, {:?}, arguments).map_err(runtime_error)?;\n",
            tool.wire_name,
        ));
        out.push_str("        let envelope_json = envelope.to_string();\n");
        if let Some(id) = tool.output {
            out.push_str(&format!(
                "        let structured = envelope.get(\"structuredContent\").ok_or_else(|| tool::Error::ResultDecoding(\"missing structuredContent\".into()))?;\n\
                 let structured_content = codecs::decode_{id}(structured)?;\n\
                 Ok(tool::{} {{ structured_content, envelope_json }})\n",
                rust_type_name(&tool.result_name),
            ));
        } else {
            out.push_str("        Ok(envelope_json)\n");
        }
        out.push_str("    }\n");
    }
    out.push_str("}\n");
    out
}

fn codecs(catalog: &Catalog) -> String {
    let mut out = String::from(
        "#![allow(dead_code, unused_mut, unused_variables)]\n\
         use crate::tool;\n\
         use serde_json::{Map, Value};\n\
         fn invalid(path: &str, reason: &str) -> tool::Error {\n\
             tool::Error::ResultDecoding(format!(\"{path}: {reason}\"))\n\
         }\n\n",
    );
    for (id, schema) in catalog.schemas.iter().enumerate() {
        let ty = rust_type_name(&schema.name);
        let value_ty = rust_type_name(&schema.value_name);
        if schema.nullable {
            out.push_str(&format!(
                "pub(crate) fn encode_{id}(value: &tool::{ty}) -> Result<Value, tool::Error> {{\n\
                     match value {{ Some(value) => encode_value_{id}(value), None => Ok(Value::Null) }}\n\
                 }}\n\
                 pub(crate) fn decode_{id}(value: &Value) -> Result<tool::{ty}, tool::Error> {{\n\
                     if value.is_null() {{ Ok(None) }} else {{ decode_value_{id}(value).map(Some) }}\n\
                 }}\n"
            ));
        }
        let suffix = if schema.nullable {
            format!("value_{id}")
        } else {
            id.to_string()
        };
        out.push_str(&format!("pub(crate) fn encode_{suffix}(value: &tool::{value_ty}) -> Result<Value, tool::Error> {{\n"));
        encode(&mut out, schema);
        out.push_str("}\n");
        out.push_str(&format!("pub(crate) fn decode_{suffix}(value: &Value) -> Result<tool::{value_ty}, tool::Error> {{\n"));
        decode(&mut out, schema);
        out.push_str("}\n\n");
    }
    out
}

fn encode(out: &mut String, schema: &Schema) {
    let path = &schema.pointer;
    match &schema.kind {
        Kind::Boolean => out.push_str("    Ok(Value::Bool(*value))\n"),
        Kind::String => out.push_str("    Ok(Value::String(value.clone()))\n"),
        Kind::Number(Number::F32 | Number::F64) => out.push_str(&format!(
            "    serde_json::Number::from_f64(f64::from(*value)).map(Value::Number).ok_or_else(|| invalid({path:?}, \"non-finite number\"))\n"
        )),
        Kind::Number(_) => out.push_str("    Ok(Value::Number((*value).into()))\n"),
        Kind::Ref(id) => out.push_str(&format!("    encode_{id}(value)\n")),
        Kind::Array(id) => out.push_str(&format!(
            "    value.iter().map(encode_{id}).collect::<Result<Vec<_>, _>>().map(Value::Array)\n"
        )),
        Kind::Enum(cases) => {
            let ty = rust_type_name(&schema.value_name);
            out.push_str("    Ok(Value::String(match value {\n");
            for case in cases {
                out.push_str(&format!("        tool::{ty}::{} => {:?},\n", rust_case_name(&case.name), case.wire_value));
            }
            out.push_str("    }.into()))\n");
        }
        Kind::Object { properties, additional } => {
            if properties.is_empty() && additional.is_none() {
                out.push_str(&format!(
                    "    match value {{ tool::{}::Empty => Ok(Value::Object(Map::new())) }}\n",
                    rust_type_name(&schema.value_name)
                ));
                return;
            }
            out.push_str("    let mut object = Map::new();\n");
            for property in properties {
                let field = rust_ident(&property.name);
                let key = &property.wire_name;
                let id = property.schema;
                if property.required {
                    out.push_str(&format!("    object.insert({key:?}.into(), encode_{id}(&value.{field})?);\n"));
                } else {
                    out.push_str(&format!(
                        "    if let Some(value) = &value.{field} {{ object.insert({key:?}.into(), encode_{id}(value)?); }}\n"
                    ));
                }
            }
            if let Some(additional) = additional {
                let values = if properties.is_empty() { "value".into() } else { format!("&value.{}", rust_ident(&additional.name)) };
                out.push_str(&format!("    for (key, value) in {values} {{\n"));
                if !properties.is_empty() {
                    out.push_str(&format!("        if matches!(key.as_str(), {}) {{ return Err(invalid({path:?}, \"extra key conflicts with a declared property\")); }}\n", keys(properties)));
                }
                out.push_str(&format!(
                    "        if object.contains_key(key) {{ return Err(invalid({path:?}, \"duplicate object key\")); }}\n\
                     object.insert(key.clone(), encode_{}(value)?);\n    }}\n",
                    additional.schema,
                ));
            }
            out.push_str("    Ok(Value::Object(object))\n");
        }
    }
}

fn decode(out: &mut String, schema: &Schema) {
    let path = &schema.pointer;
    match &schema.kind {
        Kind::Boolean => out.push_str(&format!("    value.as_bool().ok_or_else(|| invalid({path:?}, \"expected boolean\"))\n")),
        Kind::String => out.push_str(&format!("    value.as_str().map(str::to_owned).ok_or_else(|| invalid({path:?}, \"expected string\"))\n")),
        Kind::Number(number) => decode_number(out, *number, path),
        Kind::Ref(id) => out.push_str(&format!("    decode_{id}(value)\n")),
        Kind::Array(id) => out.push_str(&format!(
            "    value.as_array().ok_or_else(|| invalid({path:?}, \"expected array\"))?.iter().map(decode_{id}).collect()\n"
        )),
        Kind::Enum(cases) => {
            let ty = rust_type_name(&schema.value_name);
            out.push_str("    match value.as_str() {\n");
            for case in cases {
                out.push_str(&format!("        Some({:?}) => Ok(tool::{ty}::{}),\n", case.wire_value, rust_case_name(&case.name)));
            }
            out.push_str(&format!("        _ => Err(invalid({path:?}, \"expected a declared enum string\")),\n    }}\n"));
        }
        Kind::Object { properties, additional } => {
            out.push_str(&format!("    let object = value.as_object().ok_or_else(|| invalid({path:?}, \"expected object\"))?;\n"));
            if properties.is_empty()
                && let Some(additional) = additional
            {
                out.push_str(&format!("    object.iter().map(|(key, value)| Ok((key.clone(), decode_{}(value)?))).collect()\n", additional.schema));
                return;
            }
            if additional.is_none() {
                let check = if properties.is_empty() { "!object.is_empty()".into() } else { format!("object.keys().any(|key| !matches!(key.as_str(), {}))", keys(properties)) };
                out.push_str(&format!("    if {check} {{ return Err(invalid({path:?}, \"unknown property in closed object\")); }}\n"));
                if properties.is_empty() {
                    out.push_str(&format!(
                        "    Ok(tool::{}::Empty)\n",
                        rust_type_name(&schema.value_name)
                    ));
                    return;
                }
            }
            out.push_str(&format!("    Ok(tool::{} {{\n", rust_type_name(&schema.value_name)));
            for property in properties {
                let field = rust_ident(&property.name);
                let key = &property.wire_name;
                let id = property.schema;
                if property.required {
                    out.push_str(&format!(
                        "        {field}: decode_{id}(object.get({key:?}).ok_or_else(|| invalid({path:?}, {:?}))?)?,\n",
                        format!("missing required property {key:?}"),
                    ));
                } else {
                    out.push_str(&format!("        {field}: object.get({key:?}).map(decode_{id}).transpose()?,\n"));
                }
            }
            if let Some(additional) = additional {
                out.push_str(&format!(
                    "        {}: object.iter().filter(|(key, _)| !matches!(key.as_str(), {})).map(|(key, value)| Ok((key.clone(), decode_{}(value)?))).collect::<Result<Vec<_>, tool::Error>>()?,\n",
                    rust_ident(&additional.name), keys(properties), additional.schema,
                ));
            }
            out.push_str("    })\n");
        }
    }
}

fn decode_number(out: &mut String, number: Number, path: &str) {
    let (ty, method) = match number {
        Number::S8 => ("i8", "as_i64"),
        Number::S16 => ("i16", "as_i64"),
        Number::S32 => ("i32", "as_i64"),
        Number::S64 => ("i64", "as_i64"),
        Number::U8 => ("u8", "as_u64"),
        Number::U16 => ("u16", "as_u64"),
        Number::U32 => ("u32", "as_u64"),
        Number::U64 => ("u64", "as_u64"),
        Number::F32 | Number::F64 => {
            out.push_str(&format!("    let number = value.as_f64().ok_or_else(|| invalid({path:?}, \"expected finite number\"))?;\n"));
            if number == Number::F32 {
                out.push_str(&format!(
                    "    if !number.is_finite() || number.abs() > f64::from(f32::MAX) {{ return Err(invalid({path:?}, \"number outside f32 range\")); }}\n\
                     let narrowed = number as f32;\n\
                     if number != 0.0 && narrowed == 0.0 {{ return Err(invalid({path:?}, \"number underflows f32\")); }}\n\
                     Ok(narrowed)\n",
                ));
            } else {
                out.push_str(&format!("    if !number.is_finite() {{ return Err(invalid({path:?}, \"non-finite number\")); }}\n    Ok(number)\n"));
            }
            return;
        }
    };
    out.push_str(&format!(
        "    let number = value.{method}().ok_or_else(|| invalid({path:?}, \"expected an integer in {ty} range\"))?;\n\
         {ty}::try_from(number).map_err(|_| invalid({path:?}, \"integer outside {ty} range\"))\n"
    ));
}

fn keys(properties: &[crate::model::Property]) -> String {
    properties
        .iter()
        .map(|property| format!("{:?}", property.wire_name))
        .collect::<Vec<_>>()
        .join(" | ")
}

fn schema(catalog: &Catalog, id: SchemaId) -> &Schema {
    catalog.schemas.get(id).expect("validated schema arena ID")
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::{Value, json};
    use std::{fs, path::Path, process::Command};

    /// Cargo subprocesses have a separate target directory to avoid holding the
    /// parent test runner's workspace lock. Artifacts stay below workspace target/.
    #[test]
    #[ignore = "compiles standalone native and wasm32-wasip2 clients with Cargo"]
    fn generated_clients_compile_and_codecs_execute() {
        let mut source: Value =
            serde_json::from_str(include_str!("../tests/fixtures/tools.json")).unwrap();
        let mut properties = serde_json::Map::new();
        for format in [
            "int8", "int16", "int32", "int64", "uint8", "uint16", "uint32", "uint64",
        ] {
            properties.insert(format.into(), json!({"type":"integer","format":format}));
        }
        for format in ["float32", "float64"] {
            properties.insert(format.into(), json!({"type":"number","format":format}));
        }
        properties.insert("nullableBool".into(), json!({"type":["boolean","null"]}));
        properties.insert(
            "optionalNullableString".into(),
            json!({"type":["string","null"]}),
        );
        properties.insert(
            "nullableList".into(),
            json!({"type":["array","null"],"items":{"type":["integer","null"]}}),
        );
        properties.insert("nullableObject".into(), json!({"type":["object","null"],"additionalProperties":false,"properties":{"x":{"type":"string"}}}));
        properties.insert(
            "emptyObject".into(),
            json!({"type":"object","additionalProperties":false}),
        );
        properties.insert(
            "nullableEmptyObject".into(),
            json!({"type":["object","null"],"additionalProperties":false}),
        );
        properties.insert(
            "odd \"field\"\n".into(),
            json!({"type":"string","enum":["x\"y","line\nbreak","foo-bar","fooBar","_☃"]}),
        );
        let tools = source.get_mut("tools").unwrap().as_array_mut().unwrap();
        tools.push(json!({
            "name":"all_values",
            "inputSchema":{
                "type":"object",
                "additionalProperties":false,
                "properties":properties,
                "required":["nullableBool"],
                "$defs":{
                    "unused":{
                        "type":"object",
                        "additionalProperties":false,
                        "properties":{"value":{"type":["string","null"],"enum":["unused-value",null]}}
                    }
                }
            },
            "outputSchema":{
                "type":"object",
                "additionalProperties":{"type":["string","null"]}
            }
        }));
        tools.push(json!({"name":"say\"hello\n","inputSchema":{"type":"object","additionalProperties":false}}));
        let catalog = crate::from_json_value(source).unwrap();
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/mcp-codegen-fixtures");
        let target = root.join("build");
        for (name, secret, catalog) in [
            ("anonymous", None, &catalog),
            ("authenticated", Some("mcp-bearer".to_owned()), &catalog),
            (
                "empty",
                None,
                &crate::parse_catalog(r#"{"tools":[]}"#).unwrap(),
            ),
        ] {
            let package = PackageName::parse(&format!("example:{name}@0.1.0")).unwrap();
            let options = GenerateOptions {
                endpoint: "http://127.0.0.1:8080/mcp".into(),
                bearer_secret: secret,
                ..GenerateOptions::default()
            };
            let mut generated = crate::generate(catalog, &package, &options).unwrap();
            generated
                .rust
                .iter_mut()
                .find(|source| source.path == "codecs.rs")
                .unwrap()
                .contents
                .push_str(&codec_checks(catalog));
            let directory = root.join(name);
            write(&directory, "Cargo.toml", &generated.cargo_toml);
            write(&directory, "wit/world.wit", &generated.wit);
            for source in generated.rust {
                write(&directory.join("src"), &source.path, &source.contents);
            }
            for dependency in generated.wit_dependencies {
                write(
                    &directory.join("wit"),
                    &dependency.path,
                    &dependency.contents,
                );
            }
            for args in [
                vec!["test", "--lib", "--quiet"],
                vec!["build", "--lib", "--target", "wasm32-wasip2", "--quiet"],
            ] {
                let output = Command::new(env!("CARGO"))
                    .args(args)
                    .arg("--manifest-path")
                    .arg(directory.join("Cargo.toml"))
                    .arg("--target-dir")
                    .arg(&target)
                    .output()
                    .unwrap();
                assert!(
                    output.status.success(),
                    "{name} fixture failed:\n{}\n{}",
                    String::from_utf8_lossy(&output.stdout),
                    String::from_utf8_lossy(&output.stderr)
                );
            }
        }
    }

    fn write(root: &Path, path: &str, contents: &str) {
        let path = root.join(path);
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(path, contents).unwrap();
    }

    fn codec_checks(catalog: &Catalog) -> String {
        let mut out = "\n#[cfg(test)] mod generated_checks {\nuse super::*;\n".to_owned();
        for (id, schema) in catalog.schemas.iter().enumerate() {
            out.push_str(&format!("#[test] fn schema_{id}() {{\n"));
            let value = sample(catalog, id);
            roundtrip(&mut out, id, &value);
            if nullable(catalog, id) {
                roundtrip(&mut out, id, &Value::Null);
            } else {
                reject(&mut out, id, &Value::Null);
            }
            let wrong = match schema.kind {
                Kind::String | Kind::Enum(_) => json!(7),
                _ => json!("wrong type"),
            };
            reject(&mut out, id, &wrong);
            match &schema.kind {
                Kind::Boolean => reject(&mut out, id, &json!(1)),
                Kind::Enum(_) => reject(&mut out, id, &json!("never-a-declared-case")),
                Kind::Number(number) => {
                    number_checks(&mut out, id, schema, *number);
                }
                Kind::Array(_) => reject(&mut out, id, &json!([{}])),
                Kind::Object {
                    properties,
                    additional,
                } => {
                    let mut object = value.as_object().unwrap().clone();
                    for property in properties {
                        let removed = object.remove(&property.wire_name).unwrap();
                        if property.required {
                            reject(&mut out, id, &Value::Object(object.clone()));
                        } else {
                            roundtrip(&mut out, id, &Value::Object(object.clone()));
                        }
                        object.insert(property.wire_name.clone(), Value::Null);
                        if nullable(catalog, property.schema) {
                            roundtrip(&mut out, id, &Value::Object(object.clone()));
                        } else {
                            reject(&mut out, id, &Value::Object(object.clone()));
                        }
                        object.insert(property.wire_name.clone(), removed);
                    }
                    if let Some(additional) = additional {
                        let field = if properties.is_empty() {
                            String::new()
                        } else {
                            format!(".{}", rust_ident(&additional.name))
                        };
                        let inner = if schema.nullable {
                            "typed.as_mut().unwrap()"
                        } else {
                            "typed"
                        };
                        out.push_str(&format!(
                            "let mut typed = decode_{id}(&serde_json::from_str::<Value>({:?}).unwrap()).unwrap();\n\
                             let entry = {inner}{field}.first().unwrap().clone();\n\
                             {inner}{field}.push(entry);\n\
                             assert!(encode_{id}(&typed).is_err());\n",
                            value.to_string(),
                        ));
                        if let Some(property) = properties.first() {
                            out.push_str(&format!(
                                "let mut typed = decode_{id}(&serde_json::from_str::<Value>({:?}).unwrap()).unwrap();\n\
                                 let (_, extra) = {inner}{field}.pop().unwrap();\n\
                                 {inner}{field}.push(({:?}.into(), extra));\n",
                                value.to_string(), property.wire_name,
                            ));
                            if !property.required {
                                out.push_str(&format!(
                                    "{inner}.{} = None;\n",
                                    rust_ident(&property.name)
                                ));
                            }
                            out.push_str(&format!("assert!(encode_{id}(&typed).is_err());\n"));
                        }
                    } else {
                        object.insert("__unknown".into(), json!(true));
                        reject(&mut out, id, &Value::Object(object));
                    }
                }
                _ => {}
            }
            out.push_str("}\n");
        }
        out.push_str("}\n");
        out
    }

    fn roundtrip(out: &mut String, id: SchemaId, value: &Value) {
        out.push_str(&format!(
            "let json = serde_json::from_str::<Value>({:?}).unwrap();\n\
             assert_eq!(encode_{id}(&decode_{id}(&json).unwrap()).unwrap(), json);\n",
            value.to_string(),
        ));
    }

    fn reject(out: &mut String, id: SchemaId, value: &Value) {
        out.push_str(&format!(
            "assert!(decode_{id}(&serde_json::from_str::<Value>({:?}).unwrap()).is_err());\n",
            value.to_string()
        ));
    }

    fn nullable(catalog: &Catalog, id: SchemaId) -> bool {
        let value = schema(catalog, id);
        value.nullable || matches!(value.kind, Kind::Ref(target) if nullable(catalog, target))
    }

    fn sample(catalog: &Catalog, id: SchemaId) -> Value {
        match &schema(catalog, id).kind {
            Kind::Boolean => json!(true),
            Kind::String => json!("value"),
            Kind::Number(Number::F32 | Number::F64) => json!(1.25),
            Kind::Number(_) => json!(7),
            Kind::Enum(cases) => json!(cases.first().unwrap().wire_value),
            Kind::Ref(id) => sample(catalog, *id),
            Kind::Array(id) => json!([sample(catalog, *id)]),
            Kind::Object {
                properties,
                additional,
            } => {
                let mut object = serde_json::Map::new();
                for property in properties {
                    object.insert(property.wire_name.clone(), sample(catalog, property.schema));
                }
                if let Some(additional) = additional {
                    object.insert("__extra".into(), sample(catalog, additional.schema));
                }
                Value::Object(object)
            }
        }
    }

    fn number_checks(out: &mut String, id: SchemaId, schema: &Schema, number: Number) {
        let (low, high, below, above) = match number {
            Number::S8 => (json!(i8::MIN), json!(i8::MAX), json!(-129), json!(128)),
            Number::S16 => (
                json!(i16::MIN),
                json!(i16::MAX),
                json!(-32769),
                json!(32768),
            ),
            Number::S32 => (
                json!(i32::MIN),
                json!(i32::MAX),
                json!(-2147483649i64),
                json!(2147483648i64),
            ),
            Number::S64 => (
                json!(i64::MIN),
                json!(i64::MAX),
                json!(-1e30),
                json!(u64::MAX),
            ),
            Number::U8 => (json!(0), json!(u8::MAX), json!(-1), json!(256)),
            Number::U16 => (json!(0), json!(u16::MAX), json!(-1), json!(65536)),
            Number::U32 => (json!(0), json!(u32::MAX), json!(-1), json!(4294967296u64)),
            Number::U64 => (json!(0), json!(u64::MAX), json!(-1), json!(1e30)),
            Number::F32 | Number::F64 => {
                let suffix = if schema.nullable {
                    format!("value_{id}")
                } else {
                    id.to_string()
                };
                let ty = if number == Number::F32 { "f32" } else { "f64" };
                out.push_str(&format!("assert!(encode_{suffix}(&{ty}::NAN).is_err());\nassert!(encode_{suffix}(&{ty}::INFINITY).is_err());\nassert!(encode_{suffix}(&{ty}::NEG_INFINITY).is_err());\n"));
                if number == Number::F32 {
                    roundtrip(out, id, &json!(f64::from(f32::MAX)));
                    roundtrip(out, id, &json!(f64::from(f32::MIN)));
                    roundtrip(out, id, &json!(f64::from(f32::MIN_POSITIVE)));
                    reject(out, id, &json!(1e39));
                    reject(out, id, &json!(-1e39));
                    reject(out, id, &json!(1e-100));
                } else {
                    roundtrip(out, id, &json!(f64::MAX));
                    roundtrip(out, id, &json!(f64::MIN));
                    roundtrip(out, id, &json!(f64::MIN_POSITIVE));
                }
                return;
            }
        };
        roundtrip(out, id, &low);
        roundtrip(out, id, &high);
        reject(out, id, &below);
        reject(out, id, &above);
        reject(out, id, &json!(1.5));
        reject(out, id, &json!(true));
    }
}
